const CX = 360, CY = 360;              // centro do canvas / do polígono
const SIDES = 9;                       // nonágono regular
const RADIUS = 260;                    // raio (circunraio) em px
const PERIOD = 7;                      // segundos por volta completa
const OMEGA = (2 * Math.PI) / PERIOD;  // rad/s; positivo = sentido horário (y para baixo)
const THETA0 = -Math.PI / 2;           // ângulo inicial (vértice no topo)

const BR = 14;          // raio das bolas
const G = 900;          // gravidade, px/s^2 (para "baixo" do ecrã)
const E = 0.82;         // restituição
const AIR_K = 0.30;     // fricção do ar (1/s)
const MU_WALL = 0.25;   // fração do deslizamento removida por contacto com a parede
const MU_BALL = 0.20;   // fração do deslizamento removida por contacto bola-bola
const SPIN_DAMP = 0.05; // amortecimento do spin (1/s)
const HSUB = 1 / 240;   // subpasso máximo de física (s)
const MAXSUB = 20000;   // limite de segurança de subpassos por step()

/* =============================== estado ============================= */

let t = 0;                       // tempo simulado (s)
let externalDriven = false;      // step() foi chamado -> RAF deixa de avançar o tempo

const balls = [];
(function seed() {
  // 13 bolas = 1 + 3 + 9 num cluster determinístico perto do centro, v = 0
  const rings = [
    { n: 1, rad: 0,   off: 0.0 },
    { n: 3, rad: 33,  off: 0.4 },
    { n: 9, rad: 66,  off: 0.1 },
  ];
  let id = 0;
  for (const ring of rings) {
    for (let i = 0; i < ring.n; i++) {
      const a = ring.off + (2 * Math.PI * i) / ring.n;
      balls.push({
        id: id,
        x: CX + ring.rad * Math.cos(a),
        y: CY + ring.rad * Math.sin(a),
        vx: 0, vy: 0,
        phi: (id % 3) * 0.6,  // orientação (spin) inicial
        w: 0                 // velocidade angular das bolas (rad/s)
      });
      id++;
    }
  }
})();

/* ============================= geometria ============================ */

function polyAngle() { return THETA0 + OMEGA * t; }

function vertices() {
  const a0 = polyAngle();
  const stepA = (2 * Math.PI) / SIDES;
  const v = new Array(SIDES);
  for (let i = 0; i < SIDES; i++) {
    const a = a0 + i * stepA;
    v[i] = { x: CX + RADIUS * Math.cos(a), y: CY + RADIUS * Math.sin(a) };
  }
  return v;
}

function closestOnSeg(px, py, ax, ay, bx, by) {
  const dx = bx - ax, dy = by - ay;
  const L2 = dx * dx + dy * dy;
  let s = ((px - ax) * dx + (py - ay) * dy) / L2;
  s = s < 0 ? 0 : (s > 1 ? 1 : s);
  return { x: ax + s * dx, y: ay + s * dy };
}

// Ponto mais próximo do centro do polígono convexo a partir de (px,py)
function closestBoundary(px, py, vs) {
  let best2 = Infinity, bx = 0, by = 0;
  for (let i = 0; i < SIDES; i++) {
    const A = vs[i], B = vs[(i + 1) % SIDES];
    const P = closestOnSeg(px, py, A.x, A.y, B.x, B.y);
    const dx = px - P.x, dy = py - P.y;
    const d2 = dx * dx + dy * dy;
    if (d2 < best2) { best2 = d2; bx = P.x; by = P.y; }
  }
  return { x: bx, y: by };
}

// Velocidade do ponto da parede (rotação rígida de OMEGA rad/s em torno de (CX,CY))
function wallVelAt(px, py) {
  const rx = px - CX, ry = py - CY;
  return { x: -OMEGA * ry, y: OMEGA * rx };
}

/* ========================== resolução colisão ======================= */

function solveWalls(vs) {
  for (const b of balls) {
    const P = closestBoundary(b.x, b.y, vs);
    let rx = b.x - P.x, ry = b.y - P.y;
    const ox = CX - P.x, oy = CY - P.y;          // direção interior em P
    const ol = Math.sqrt(ox * ox + oy * oy) || 1;
    const inward = (rx * ox + ry * oy) / ol;     // < 0 -> bola do lado de fora
    let d = Math.sqrt(rx * rx + ry * ry);
    let nx, ny;

    if (inward <= 0 || d < 1e-9) {
      // caso de segurança: projetar de volta para dentro
      b.x = P.x + (ox / ol) * BR;
      b.y = P.y + (oy / ol) * BR;
      nx = ox / ol; ny = oy / ol;
    } else if (d < BR) {
      nx = rx / d; ny = ry / d;
      const pen = BR - d;
      b.x += nx * pen;
      b.y += ny * pen;
    } else {
      continue; // sem contacto
    }

    // velocidade da parede no ponto de contacto
    const wv = wallVelAt(P.x, P.y);
    const rlx = b.vx - wv.x, rly = b.vy - wv.y;
    const vn = rlx * nx + rly * ny;
    if (vn < 0) {
      // impulso de restituição (massa unitária)
      const j = -(1 + E) * vn;
      b.vx += j * nx;
      b.vy += j * ny;
      // fricção de contacto: remover uma fração do deslizamento da superfície
      const tx = -ny, ty = nx;                     // tangente
      const slip = (b.vx - wv.x) * tx + (b.vy - wv.y) * ty + b.w * BR;
      const corr = MU_WALL * slip;
      b.vx -= 0.5 * corr * tx;
      b.vy -= 0.5 * corr * ty;
      b.w  -= (0.5 * corr) / BR;
    }
  }
}

function solveBalls() {
  const n = balls.length;
  const minD = 2 * BR;
  for (let i = 0; i < n; i++) {
    const A = balls[i];
    for (let k = i + 1; k < n; k++) {
      const B = balls[k];
      const dx = B.x - A.x, dy = B.y - A.y;
      const d2 = dx * dx + dy * dy;
      if (d2 >= minD * minD) continue;
      const d = Math.sqrt(d2);
      let nx, ny;
      if (d > 1e-9) { nx = dx / d; ny = dy / d; } else { nx = 1; ny = 0; }

      // separação positional 50/50
      const pen = minD - d;
      A.x -= 0.5 * pen * nx; A.y -= 0.5 * pen * ny;
      B.x += 0.5 * pen * nx; B.y += 0.5 * pen * ny;

      const rlx = B.vx - A.vx, rly = B.vy - A.vy;
      const vn = rlx * nx + rly * ny;
      if (vn < 0) {
        const j = -(1 + E) * vn * 0.5;   // massas iguais (unitárias)
        A.vx -= j * nx; A.vy -= j * ny;
        B.vx += j * nx; B.vy += j * ny;
      }
      // fricção de contacto (distribui entre velocidade linear e spin)
      const tx = -ny, ty = nx;
      const slip = rlx * tx + rly * ty - (A.w + B.w) * BR;
      if (slip !== 0) {
        const J = MU_BALL * slip / 6;              // massa 1, I = 1/2 m r^2
        A.vx += J * tx; A.vy += J * ty;
        B.vx -= J * tx; B.vy -= J * ty;
        const dw = (2 * J) / BR;
        A.w += dw; B.w += dw;
      }
    }
  }
}

/* ============================ integração ============================ */

function simSubstep(h) {
  // forças
  for (const b of balls) {
    b.vy += G * h;
    const drag = 1 - AIR_K * h;
    b.vx *= drag;
    b.vy *= drag;
    b.x  += b.vx * h;
    b.y  += b.vy * h;
    b.w  *= (1 - SPIN_DAMP * h);
  }

  const vs = vertices();
  for (let iter = 0; iter < 5; iter++) {
    solveWalls(vs);
    solveBalls();
  }

  // garantia forte: nenhuma bola fica fora do polígono
  for (const b of balls) {
    const P = closestBoundary(b.x, b.y, vs);
    const rx = b.x - P.x, ry = b.y - P.y;
    const ox = CX - P.x, oy = CY - P.y;
    if ((rx * ox + ry * oy) <= 0) {
      const ol = Math.sqrt(ox * ox + oy * oy) || 1;
      b.x = P.x + (ox / ol) * BR;
      b.y = P.y + (oy / ol) * BR;
    } else {
      const d = Math.sqrt(rx * rx + ry * ry);
      if (d < BR) {
        b.x += (rx / d) * (BR - d);
        b.y += (ry / d) * (BR - d);
      }
    }
  }

  for (const b of balls) b.phi += b.w * h;
}

function advance(dt) {
  if (!(dt > 0)) return;
  t += dt;
  let nSub = Math.ceil(dt / HSUB - 1e-9);
  if (nSub < 1) nSub = 1;
  if (nSub > MAXSUB) nSub = MAXSUB;
  const h = dt / nSub;
  for (let i = 0; i < nSub; i++) simSubstep(h);
}

/* ============================== render ============================== */

const canvas = document.getElementById("c");
const ctx = canvas.getContext("2d");

const palette = balls.map((b, i) => {
  const hue = Math.round((360 / balls.length) * i);
  return {
    light: `hsl(${hue}, 90%, 74%)`,
    base:  `hsl(${hue}, 80%, 58%)`,
    dark:  `hsl(${hue}, 85%, 42%)`
  };
});

function render() {
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = "#11151d";
  ctx.fillRect(0, 0, W, H);

  // halo de fundo
  const bg = ctx.createRadialGradient(CX, CY, 60, CX, CY, 340);
  bg.addColorStop(0, "rgba(90,130,255,0.10)");
  bg.addColorStop(1, "rgba(90,130,255,0.00)");
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  // polígono
  const vs = vertices();
  ctx.beginPath();
  ctx.moveTo(vs[0].x, vs[0].y);
  for (let i = 1; i < SIDES; i++) ctx.lineTo(vs[i].x, vs[i].y);
  ctx.closePath();
  ctx.fillStyle = "rgba(96,150,255,0.06)";
  ctx.fill();
  ctx.lineJoin = "round";
  ctx.lineWidth = 4;
  ctx.strokeStyle = "#5f9dff";
  ctx.stroke();
  // vértices
  ctx.fillStyle = "#a8c8ff";
  for (let i = 0; i < SIDES; i++) {
    ctx.beginPath();
    ctx.arc(vs[i].x, vs[i].y, 5, 0, Math.PI * 2);
    ctx.fill();
  }

  // bolas (número rotação com o spin)
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  for (let i = 0; i < balls.length; i++) {
    const b = balls[i];
    const col = palette[i];
    ctx.save();
    ctx.translate(b.x, b.y);
    ctx.rotate(b.phi);
    const g = ctx.createRadialGradient(-5, -6, 2, 0, 0, BR + 1);
    g.addColorStop(0, col.light);
    g.addColorStop(0.55, col.base);
    g.addColorStop(1, col.dark);
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(0, 0, BR, 0, Math.PI * 2);
    ctx.fill();
    ctx.lineWidth = 1.5;
    ctx.strokeStyle = "rgba(0,0,0,0.35)";
    ctx.stroke();
    ctx.fillStyle = "#14161c";
    ctx.font = "bold 13px ui-monospace, Menlo, Consolas, monospace";
    ctx.fillText(String(b.id), 0, 0.5);
    ctx.restore();
  }
}

/* ====================== contrato de verificação ===================== */

window.__bench = {
  getState() {
    return {
      t: t,
      poly: {
        n: SIDES,
        radius: RADIUS,
        cx: CX,
        cy: CY,
        angle: THETA0 + OMEGA * t,
        periodSec: PERIOD
      },
      balls: balls.map((b) => ({
        id: b.id,
        x: b.x,
        y: b.y,
        r: BR,
        vx: b.vx,
        vy: b.vy
      }))
    };
  },
  step(dtSeconds) {
    const dt = Number(dtSeconds);
    if (!(dt > 0) || !isFinite(dt)) return;
    externalDriven = true;   // a partir daqui, o RAF só desenha
    advance(dt);
    render();
  }
};

/* ===================== animação (requestAnimationFrame) ============= */

let lastNow = null;
function frame(now) {
  if (lastNow == null) lastNow = now;
  let dt = (now - lastNow) / 1000;
  lastNow = now;
  if (!externalDriven) {
    if (!(dt > 0)) dt = 0;
    if (dt > 0.25) dt = 0.25;
    if (dt > 0) advance(dt);
  }
  render();
  requestAnimationFrame(frame);
}

render();
requestAnimationFrame(frame);
})();
</script>
</body>
</html>
